 if(p.demoRows){document.querySelectorAll('.kodo-art-table').forEach(table=>{const head=table.querySelector('.kodo-art-table-thead .kodo-art-table-row'),body=table.querySelector('.kodo-art-table-tbody');if(!head||!body)return;const actionIndex=Array.from(head.children).findIndex(h=>h.textContent.trim()==='操作');const sampledDateCells=Array.from(body.querySelector('.kodo-art-table-row:not(.kodo-art-table-measure-row)')?.children||[]).map(c=>c.textContent.trim());const sampledStatusRows=Array.from(body.children).filter(r=>r.classList.contains('kodo-art-table-row')&&!r.classList.contains('kodo-art-table-measure-row')).map(r=>Array.from(r.children).map(c=>c.cloneNode(true)));const sourceActionCell=Array.from(body.children).find(r=>r.classList.contains('kodo-art-table-row')&&!r.classList.contains('kodo-art-table-measure-row'))?.children[actionIndex];const sourceActionClones=Array.from(body.children).filter(r=>r.classList.contains('kodo-art-table-row')&&!r.classList.contains('kodo-art-table-measure-row')).map(r=>(Array.from(r.children).reverse().find(c=>c.classList.contains('kodo-art-table-cell-fix-right'))||r.children[actionIndex])?.cloneNode(true)).filter(Boolean);table.querySelectorAll('.kodo-art-table-empty-placeholder').forEach(e=>e.remove());Array.from(body.children).filter(e=>!e.classList.contains('kodo-art-table-measure-row')).forEach(e=>e.remove());for(let i=0;i<10;i++){const row=document.createElement('div');row.className='kodo-art-table-row';row.style.cssText='display:flex;position:relative;min-height:32px;height:32px;';Array.from(head.children).flatMap(h=>h.hasAttribute('colspan')?Array.from(h.querySelectorAll('.kodo-art-table-header-cell-child')):[h]).forEach((h,j)=>{const cell=document.createElement('div');cell.className='kodo-art-table-cell';cell.style.cssText=h.style.cssText;cell.style.height='32px';cell.style.background='#fff';cell.style.zIndex='35';cell.style.display='flex';cell.style.alignItems='center';cell.style.padding='0 8px';const label=h.textContent.trim();if(!label){cell.textContent=String(i+1);}else if(label==='操作'){cell.classList.add('demo-row-action');const actionTemplate=sourceActionClones[i%sourceActionClones.length];if(actionTemplate)cell.innerHTML=actionTemplate.innerHTML;cell.style.zIndex='45';}else if(/编号|单号/.test(label)){cell.textContent='DEMO-'+String(i+1).padStart(4,'0');cell.style.color='#1686ae';}else if(/时间|日期/.test(label)){const sampled=sampledDateCells[j]||'';cell.textContent=/\d{1,2}:\d{2}:\d{2}/.test(sampled)?'2026-01-01 08:00:00':/\d{1,2}:\d{2}/.test(sampled)||!sampled&&/时间/.test(label)?'2026-01-01 08:00':'2026-01-01';}else if(/状态/.test(label)){cell.classList.add('demo-status-cell');const sample=sampledStatusRows[i%sampledStatusRows.length]?.[j];if(sample)cell.innerHTML=sample.innerHTML;else cell.textContent='—';}else if(/类型|属性/.test(label)){cell.classList.add('demo-enum-cell');const sample=sampledStatusRows[i%sampledStatusRows.length]?.[j];if(sample)cell.innerHTML=sample.innerHTML;else cell.textContent='—';}else if(/名称|人员|创建人|更新人|审批人|供应商|客户/.test(label)){cell.textContent='演示条目 '+String.fromCharCode(65+i);}else if(/来源/.test(label)){cell.textContent='演示关联单据';}else if(/数|量|价|金额|成本|工资|工时/.test(label)){cell.textContent=String(120+i*10);}else if(/单位/.test(label)){cell.textContent='包';}else{cell.textContent='—';}row.append(cell);});body.append(row);}});}
